{{ config(materialized='table') }}

with
quarantined as (
    select
        benchmark_id,
        benchmark_name,
        index_date,
        index_value,
        currency,
        source_system,
        violation_00,
        violation_01,
        violation_02
    from {{ ref("reference__benchmark_index_returns__checked") }}
),
violations as (
    select
        'benchmark_id_not_null' as rule_name,
        benchmark_id,
        benchmark_name,
        index_date,
        index_value,
        currency,
        source_system
    from quarantined
    where violation_00

    union all

    select
        'index_date_not_null' as rule_name,
        benchmark_id,
        benchmark_name,
        index_date,
        index_value,
        currency,
        source_system
    from quarantined
    where violation_01

    union all

    select
        'index_value_not_null' as rule_name,
        benchmark_id,
        benchmark_name,
        index_date,
        index_value,
        currency,
        source_system
    from quarantined
    where violation_02
)

select
    rule_name,
    benchmark_id,
    benchmark_name,
    index_date,
    index_value,
    currency,
    source_system
from violations
